svg.script:

function openBase64Tab() {
  // De HTML inhoud opgeslagen als een Base64-string in een variabele
  // Dit is de Base64 vertaling van een simpel HTML-document
  const htmlBase64 = "";

  // Open een nieuw leeg tabblad
  const newTab = window.open('about:blank', '_blank');

  if (newTab) {
    // Decodeer de Base64-string naar normale leesbare HTML tekst
    const decodedHtml = decodeURIComponent(escape(atob(htmlBase64)));

    // Schrijf de gedecodeerde HTML naar het nieuwe tabblad
    newTab.document.write(decodedHtml);
    newTab.document.close();
  } else {
    alert('Pop-up blocker houdt het openen van het tabblad tegen.');
  }
}
